import itertools
sheet = 'W1::Allowed assignments'
rows = data_rows(sheet, {'L': 'string', 'M': 'string', 'N': 'number'}, 812, 820)
costs = {(cell(sheet, f'L{r}'), cell(sheet, f'M{r}')): num(sheet, f'N{r}') for r in rows}
tasks = sorted(list(set(k[0] for k in costs)))
workers = list(set(k[1] for k in costs))
min_cost = 999999
for p in itertools.permutations(workers, len(tasks)):
    if all((t, w) in costs for t, w in zip(tasks, p)):
        c = sum(costs[(t, w)] for t, w in zip(tasks, p))
        if c < min_cost:
            min_cost = c
result = min_cost

